  'useEverywhere.modalAria': 'Haszn├íld az Open Designt mindenhol',
  'useEverywhere.modalTitle': 'Haszn├íld az Open Designt mindenhol',
  'useEverywhere.modalSubtitle': 'Illeszd be az Open Designt b├írmely IDE-be, agentbe vagy szkriptbe ΓÇö CLI, HTTP, MCP ├⌐s Skills. Haszn├íld a ΓÇ₧├Ütmutat├│ m├ísol├ísa agenthezΓÇ¥ lehet┼æs├⌐get, ├⌐s illeszd be a Claude Code, Codex, Cursor, openclaw vagy hermes fel├╝letre a teljes be├íll├¡t├íshoz.',
  'useEverywhere.closeAria': 'ΓÇ₧Haszn├ílat mindenholΓÇ¥ bez├ír├ísa',
