  'chat.designToolbox.prompt.selectedSkill': 'Kiv├ílasztott skill: {skill}. Haszn├íld ezt els┼ædleges munkafolyamatk├⌐nt ebben a k├╢rben.',
  'chat.designToolbox.prompt.noSkill': 'Ha nincs konkr├⌐t egyez┼æ skill, el┼æsz├╢r v├ílaszd ki a legjobb kombin├íci├│t az el├⌐rhet┼æ skillek, MCP-k, pluginok, csatlakoz├│k ├⌐s diz├íjnf├íjlok k├╢z├╝l.',
  'chat.designToolbox.prompt.autoMatchIntro': 'L├⌐pj fel kreat├¡vigazgat├│-orchestratork├⌐nt, ├⌐s fejezz be egy diz├íjn-munkafolyamatot:',
  'chat.designToolbox.prompt.autoMatchStep1': '1. El┼æsz├╢r hat├írozd meg, mit jelent a ΓÇ₧j├│l kin├⌐z┼æ diz├íjnΓÇ¥: c├⌐lk├╢z├╢ns├⌐g, ├╝zleti c├⌐l, m├írka├⌐rzet, st├¡lusreferenci├ík, inform├íci├│s┼▒r┼▒s├⌐g, sz├¡n-/tipogr├ífia-/mozg├ís-/asset-szabv├ínyok, valamint a ker├╝lend┼æ AI-/sablonmint├ízatok.',
  'chat.designToolbox.prompt.autoMatchStep2': '2. Keresd ├ít ├⌐s illeszd hozz├í a fenti teljes er┼æforr├ísindexet. Ne csak a diz├íjn-eszk├╢zt├ír aj├ínl├ísait haszn├íld; ahol hasznos, kombin├íld a skilleket, MCP-ket, pluginokat, csatlakoz├│kat ├⌐s diz├íjnf├íjlokat.',
  'chat.designToolbox.prompt.autoMatchStep3': '3. Ha a c├⌐lpont vagy az eszt├⌐tikai m├⌐rce m├⌐g mindig nem vil├ígos, ir├íny├¡ts v├⌐ges v├ílaszt├ísi lehet┼æs├⌐gekkel vagy ┼▒rlap jelleg┼▒ fel├╝lettel, ├⌐s adj meg egy aj├ínlott alap├⌐rtelmez├⌐st. Ha el├⌐gg├⌐ vil├ígos, hajtsd v├⌐gre k├╢zvetlen├╝l a k├╢vetkez┼æ l├⌐p├⌐st.',
  'chat.designToolbox.prompt.autoMatchStep4': '4. Fejezd be a folyamatot ebben a sorrendben: diagn├│zis -> st├¡lusir├íny -> er┼æforr├ísv├ílaszt├ís -> konkr├⌐t szerkeszt├⌐s/gener├íl├ís -> ellen┼ærz├⌐s. Minden l├⌐p├⌐sn├⌐l magyar├ízd el, mi├⌐rt ezeket az er┼æforr├ísokat v├ílasztottad, ├⌐s mit kell legk├╢zelebb meger┼æs├¡teni.',
  'chat.designToolbox.prompt.motion': 'Adj kiv├íl├│ min┼æs├⌐g┼▒ mozg├íst az aktu├ílis HTML / oldalelemhez: v├ílaszd ki a leghasznosabb 1-2 bel├⌐p┼æ, g├╢rget├⌐si, ├íllapot├ítmeneti vagy mikrointerakci├│s pillanatot. Tartsd visszafogottan, r├⌐szes├¡tsd el┼ænyben a transform / opacity megold├ísokat, ├⌐s ├⌐p├¡ts be prefers-reduced-motion tartal├⌐k megold├ísokat.',
  'chat.designToolbox.prompt.motionPolish': 'Vizsg├íld fel├╝l ├⌐s finom├¡tsd a megl├⌐v┼æ mozg├ís id┼æz├¡t├⌐s├⌐t, gyorsul├ís├ít, teljes├¡tm├⌐ny├⌐t ├⌐s akad├ílymentess├⌐g├⌐t. T├ívol├¡tsd el a hirtelen, olcs├│ vagy az olvashat├│s├ígot ront├│ anim├íci├│kat; sz├╝ks├⌐g eset├⌐n haszn├ílj kifinomultabb id┼ævonalat.',
  'chat.designToolbox.prompt.antiAiPolish': 'V├⌐gezz egy AI-├⌐rzet elleni finom├¡t├ísi k├╢rt: t├ívol├¡tsd el a sablonos elrendez├⌐seket, az olcs├│ gradienseket/ragyog├ísokat, az ├⌐rtelmetlen k├írtyahalmokat ├⌐s a hom├ílyos sz├╢vegeket. ┼Érizd meg az inform├íci├│t, ├⌐s tedd olyann├í, mintha egy val├│di diz├íjner adta volna ├ít.',
  'chat.designToolbox.prompt.visualPolish': 'Finom├¡tsd ezt a diz├íjnt, am├¡g kiad├ísra k├⌐sz nem lesz: ellen┼ærizd a hierarchi├ít, a tipogr├ífi├ít, a t├⌐rk├╢z├╢ket, a reszponz├¡v viselked├⌐st, a gomb├íllapotokat, az ├╝res/bet├╢lt├⌐si/hiba├íllapotokat ├⌐s az akad├ílymentess├⌐get; k├╢zvetlen├╝l jav├¡tsd ki a legfontosabb probl├⌐m├íkat.',
  'chat.designToolbox.prompt.imageGen': 'K├⌐sz├¡tsd el a k├╢vetkez┼æ vizu├íliseszk├╢z-tervet ehhez a diz├íjnhoz: szakaszreferenci├ík, hero-eszk├╢z├╢k, illusztr├íci├│k, ikonok, k├╢z├╢ss├⌐gi k├⌐pek vagy moodboard. El┼æsz├╢r d├╢ntsd el, milyen t├¡pus├║ k├⌐p hi├ínyzik, majd adj v├⌐grehajthat├│ gener├íl├ísi prompteket / f├íjltervet.',
